contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum1, uint minSum2, address logAddr1, address logAddr2) public {
        bool revertedBefore;
        c.SetMinSum(minSum1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedBefore = true; } else { revertedBefore = false; }
        require(!revertedBefore, "First SetMinSum should succeed");

        bool revertedLogBefore;
        c.SetLogFile(logAddr1); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedLogBefore = true; } else { revertedLogBefore = false; }
        require(!revertedLogBefore, "First SetLogFile should succeed");

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfterMin;
        c.SetMinSum(minSum2); bool __rev2 = __ESBMC_reverted(); if (__rev2) { revertedAfterMin = true; } else { revertedAfterMin = false; }

        bool revertedAfterLog;
        c.SetLogFile(logAddr2); bool __rev3 = __ESBMC_reverted(); if (__rev3) { revertedAfterLog = true; } else { revertedAfterLog = false; }

        assert(revertedAfterMin && revertedAfterLog);
    }

    receive() external payable {}
}

