pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 minSum1, uint256 minSum2, address logAddr1, address logAddr2) internal {
        bool revertedBefore;
        try c.SetMinSum(minSum1) { revertedBefore = false; } catch { revertedBefore = true; }
        vm.assume(!revertedBefore);
        bool revertedLogBefore;
        try c.SetLogFile(logAddr1) { revertedLogBefore = false; } catch { revertedLogBefore = true; }
        vm.assume(!revertedLogBefore);
        try c.Initialized() {} catch { return; }
        bool revertedAfterMin;
        try c.SetMinSum(minSum2) { revertedAfterMin = false; } catch { revertedAfterMin = true; }
        bool revertedAfterLog;
        try c.SetLogFile(logAddr2) { revertedAfterLog = false; } catch { revertedAfterLog = true; }
        assertTrue(revertedAfterMin && revertedAfterLog);
    }

    function testFuzz_run(uint256 minSum1, uint256 minSum2, address logAddr1, address logAddr2) public {
        vm.assume(logAddr1.code.length == 0 && uint160(logAddr1) > 0xffff && logAddr1 != address(this) && logAddr1 != address(c) && logAddr1 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr1 != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr1 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr1 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(logAddr2.code.length == 0 && uint160(logAddr2) > 0xffff && logAddr2 != address(this) && logAddr2 != address(c) && logAddr2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr2 != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(minSum1, minSum2, logAddr1, logAddr2);
    }

    receive() external payable {}
}
